template<class T>
struct abstract_array_probe
{
  template<class U>
  static double check(U (*)[1]);

  template<class U>
  static char check(...);

  enum
  {
    value = sizeof(abstract_array_probe<T>::template check<T>(0)) == sizeof(char)
  };
};

struct abstract_array_concrete
{
  virtual void f()
  {
  }
};

struct abstract_array_abstract
{
  virtual void f() = 0;
};

int main()
{
  if(abstract_array_probe<abstract_array_concrete>::value)
  {
    return 1;
  }
  return abstract_array_probe<abstract_array_abstract>::value ? 0 : 2;
}

template<class T, T v>
struct integral_constant { static const T value = v; };

typedef integral_constant<bool, true> true_type;
typedef integral_constant<bool, false> false_type;

template<bool B, class T = void>
struct enable_if_c { typedef T type; };

template<class T>
struct enable_if_c<false, T> {};

template<class T>
struct remove_reference { typedef T type; };

template<class T>
struct remove_reference<T&> { typedef T type; };

template<class T>
struct remove_reference<T&&> { typedef T type; };

template<class Base, class Derived>
using is_base_of = false_type;

template<class... Cond>
struct all_false : false_type {};

template<class... T>
struct all_false<integral_constant<T, false>...> : true_type {};

template<class... T>
struct vector {
  vector() {}

  template<class... U,
           class = typename enable_if_c<
             all_false<
               is_base_of<vector, typename remove_reference<U>::type>...
             >::value
           >::type>
  explicit vector(U&&... u) {}
};

int main()
{
  vector<int, int, int, char const*> v(1, 2, 3, (char const*)0);
  return 0;
}

template<bool, class T = void>
struct enable_if {};

template<class T>
struct enable_if<true, T> {
  typedef T type;
};

template<bool B, class T = void>
using enable_if_t = typename enable_if<B, T>::type;

struct Policy {};

template<class T>
struct is_ptr {
  static const bool value = false;
};

template<class T>
struct is_ptr<T*> {
  static const bool value = true;
};

template<class T>
struct iterator_traits;

template<class T>
struct iterator_traits<T*> {
  typedef long difference_type;
};

template<class I>
using iter_diff_t = typename iterator_traits<I>::difference_type;

template<class A, class B>
struct Pair {
  A first;
  B second;
};

template<class P>
struct IterOps {
  template<class Iter>
  using difference_type = iter_diff_t<Iter>;
};

template<class P, class In, class Out, enable_if_t<is_ptr<In>::value, int> = 0>
Pair<In, Out> helper(In first, typename IterOps<P>::template difference_type<In> n, Out result) {
  Pair<In, Out> p = {first, result};
  return p;
}

template<class P, class In, class Out, enable_if_t<!is_ptr<In>::value, int> = 0>
Pair<In, Out> helper(In first, typename IterOps<P>::template difference_type<In> n, Out result) {
  Pair<In, Out> p = {first, result};
  return p;
}

int main() {
  char src_buf[2] = {'a', 'b'};
  char dst_buf[2] = {};
  char* src = src_buf;
  char* dst = dst_buf;
  return helper<Policy>(src, iter_diff_t<char*>(2), dst).second - dst;
}

